contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller) public {
        require(caller != address(0));
        address beforeOwner = c.owner();
        bool reverted;
        if (caller == address(this)) {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            return;
        }
        address afterOwner = c.owner();
        assert((caller == beforeOwner && !reverted && afterOwner == newOwner) || (caller != beforeOwner && reverted && afterOwner == beforeOwner));
    }
}

