contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public payable {
        address beforeOwner = c.owner();
        bool reverted;
        if (caller == beforeOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (caller == beforeOwner) {
            assert(!reverted && c.owner() == newOwner);
        } else {
            assert(reverted && c.owner() == beforeOwner);
        }
    }

    receive() external payable {}
}

